import {money} from './engine.js';
import {validateDocument,compareDocuments,correctionDraft,reviewedExport,reviewCsv} from './matching-engine.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let invoice=null,po=null,result=null,reviewed=false;
const root=document.createElement('section');root.id='matching-page';root.innerHTML=`<div class="match-hero"><div><span class="eyebrow">THE $60 EXCEPTION</span><h2>Catch the difference.<br>Make the next step easy.</h2><p>Follow one invoice from intake to an evidence-backed correction request.</p></div><div class="hero-equation"><span>INVOICED</span><b>$660</b><i>vs.</i><b>$600</b><span>ORDERED</span></div></div><div class="match-steps"><span><b>1</b> Add documents</span><span><b>2</b> Compare & explain</span><span><b>3</b> Draft a correction</span><span><b>4</b> Review & export</span></div><section class="panel match-intake"><div class="panel-heading"><div><h2>Start with the source documents</h2><p>Upload both sample JSON files or load the example in one click. USD only; files stay in this browser.</p></div><button id="load-pair" class="button primary">Load $60 example</button></div><div class="pair-upload"><div><label for="match-invoice">Invoice document</label><input id="match-invoice" type="file" accept=".json,application/json"><a href="samples/matching-invoice.json" download>↓ Download sample invoice (.json)</a></div><div><label for="match-po">Purchase order</label><input id="match-po" type="file" accept=".json,application/json"><a href="samples/matching-po.json" download>↓ Download sample purchase order (.json)</a></div></div><p class="match-note">This demo reads structured JSON documents and calculates differences. PDF/image OCR and email sending are not connected.</p><div id="match-error" class="match-error" role="alert" hidden></div><div class="panel-footer"><span id="pair-status">Add an invoice and its purchase order to begin.</span><button id="compare-pair" class="button primary" disabled>Compare documents →</button></div></section><div id="pair-documents" class="pair-documents"></div><section id="match-results" hidden></section><div id="match-message" role="status" class="match-message"></div>`;
$('.content').insertBefore(root,$('footer'));
function message(s){$('#match-message').textContent=s;}
function error(e){$('#match-error').hidden=false;$('#match-error').textContent=e.message;}
function invalidate(){result=null;reviewed=false;$('#match-results').hidden=true;$('#match-results').innerHTML='';message('');$('#match-error').hidden=true;}
function documentCard(d,title){return `<article class="source-card"><div class="source-heading"><span class="eyebrow">${title}</span><span class="demo-badge">SOURCE DOCUMENT</span></div><h3>${esc(d.vendor)}</h3><div class="source-meta"><span>${esc(d.number)}</span><span>PO reference: ${esc(d.poNumber)}</span></div><table><thead><tr><th>LINE / ITEM</th><th>QTY</th><th>UNIT</th><th>AMOUNT</th></tr></thead><tbody>${d.lines.map((l,i)=>`<tr class="${result?.lines.some(r=>r.changed&&r.sku.toLowerCase()===l.sku.toLowerCase())?'evidence-highlight':''}"><td><small>Line ${i+1} · ${esc(l.sku)}</small><strong>${esc(l.description)}</strong></td><td>${l.quantity}</td><td>${money(l.unitPrice)}</td><td>${money(l.quantity*l.unitPrice)}</td></tr>`).join('')}</tbody></table><div class="source-totals"><span>Tax ${money(d.tax)}</span><strong>Total ${money(d.total)}</strong></div><details><summary>View original structured document</summary><pre>${esc(JSON.stringify(d,null,2))}</pre></details><p class="hint">${esc(d.note||'Imported document. Verify the source before making a decision.')}</p></article>`;}
function renderSources(){ $('#pair-documents').innerHTML=(invoice?documentCard(invoice,'INVOICE'):'')+(po?documentCard(po,'PURCHASE ORDER'):'');$('#compare-pair').disabled=!(invoice&&po);$('#pair-status').textContent=invoice&&po?'Two documents loaded. Ready to compare.':invoice||po?'One document loaded. Add the other to continue.':'Add an invoice and its purchase order to begin.';}
async function upload(e,kind){const file=e.target.files[0];if(!file)return;invalidate();if(kind==='invoice')invoice=null;else po=null;try{if(file.size>500000||!file.name.toLowerCase().endsWith('.json'))throw Error('Choose a .json file under 500 KB using the sample format.');const d=validateDocument(JSON.parse(await file.text()),kind);if(kind==='invoice')invoice=d;else po=d;}catch(e){error(e instanceof SyntaxError?Error('This file is not valid JSON. Download a sample to see the expected format.'):e);}renderSources();}
$('#match-invoice').onchange=e=>upload(e,'invoice');$('#match-po').onchange=e=>upload(e,'purchase_order');
$('#load-pair').onclick=async()=>{invalidate();$('#load-pair').disabled=true;try{const [i,p]=await Promise.all(['samples/matching-invoice.json','samples/matching-po.json'].map(async url=>{const r=await fetch(url);if(!r.ok)throw Error('Sample documents could not load. Please try again.');return r.json();}));invoice=validateDocument(i,'invoice');po=validateDocument(p,'purchase_order');$('#match-invoice').value='';$('#match-po').value='';renderSources();message('Sample documents loaded. Compare them to find the discrepancy.');}catch(e){error(e);}finally{$('#load-pair').disabled=false;}};
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#compare-pair').onclick=()=>{invalidate();try{result=compareDocuments(invoice,po);renderSources();renderResults();$('#match-results').scrollIntoView({behavior:'smooth',block:'start'});}catch(e){error(e);}};
function renderResults(){const changed=result.lines.filter(l=>l.changed);const mismatch=result.hasDiscrepancy;$('#match-results').hidden=false;$('#match-results').innerHTML=`<div class="result-banner ${mismatch?'':'matched'}"><div><span class="eyebrow">${mismatch?'EXCEPTION DETECTED':'COMPARISON COMPLETE'}</span><h2>${mismatch?`${money(Math.abs(result.differenceCents)/100)} net ${result.differenceCents<0?'undercharge':'overcharge'}`:'Invoice matches the purchase order'}</h2><p>${mismatch?`${changed.length} changed line item${changed.length===1?'':'s'}${result.taxDifferenceCents?' plus a tax difference':''}. Review the evidence before contacting the vendor.`:'Amounts and line items agree. Payment still requires your separate approval.'}</p></div><span class="payment-hold">${mismatch?'PAYMENT ON HOLD':'PAYMENT NOT APPROVED'}</span></div><section class="panel evidence-panel"><div class="panel-heading"><div><h2>The evidence</h2><p>Matched using vendor, PO reference and SKU. Line numbers point to the source documents above.</p></div></div><div class="evidence-list">${result.lines.map(l=>`<article class="evidence-row ${l.changed?'changed':''}"><div><strong>${esc(l.description)}</strong><small>${esc(l.sku)} · ${l.changed?'Difference found':'Matched'}</small></div><div><small>INVOICE · LINE ${l.invoiceLine??'MISSING'}</small><strong>${l.invoice?`${l.invoice.quantity} × ${money(l.invoice.unitPrice)} = ${money(l.invoicedCents/100)}`:'Not on invoice'}</strong></div><div><small>PO · LINE ${l.poLine??'MISSING'}</small><strong>${l.po?`${l.po.quantity} × ${money(l.po.unitPrice)} = ${money(l.expectedCents/100)}`:'Not on PO'}</strong></div><b>${l.changed?money(l.differenceCents/100):'✓'}</b></article>`).join('')}${result.taxDifferenceCents?`<div class="check">Tax difference: ${money(result.taxDifferenceCents/100)}. Invoice tax ${money(invoice.tax)}; PO tax ${money(po.tax)}.</div>`:''}</div><div class="evidence-explanation">${changed.length===1&&changed[0].invoice?.quantity===changed[0].po?.quantity?`${changed[0].invoice.quantity} units × (${money(changed[0].invoice.unitPrice)} invoiced − ${money(changed[0].po.unitPrice)} ordered) = <strong>${money(changed[0].differenceCents/100)} line difference.</strong>`:'The net difference is the invoice total minus the purchase order total. Opposing line differences may cancel out.'} ${mismatch?'The original documents remain unchanged.':''}</div></section><div class="resolution-grid"><section class="panel correction-panel"><div class="panel-heading"><div><h2>Correction request</h2><p>An editable draft grounded in the comparison. You decide what to send.</p></div></div><div class="resolution-body">${mismatch?'<button id="make-draft" class="button secondary">Draft correction request</button><label for="correction-text" class="draft-label" hidden>Review and edit your message</label><textarea id="correction-text" rows="14" hidden></textarea><button id="download-draft" class="text-button" hidden>↓ Download draft (.txt)</button>':'<p>No correction request needed for these documents.</p>'}<p class="hint">Draft only. Nothing is sent automatically.</p></div></section><section class="panel export-panel"><div class="panel-heading"><div><h2>Review & export</h2><p>Record your review without authorizing payment.</p></div></div><div class="resolution-body"><div class="hold-card"><strong>${mismatch?'Awaiting vendor correction':'Awaiting user approval'}</strong><p>${mismatch?'Export retains the $'+(Math.abs(result.differenceCents)/100).toFixed(2)+' difference and ON_HOLD status. Reviewing does not resolve the discrepancy.':'Export marks the evidence reviewed and payment NOT_APPROVED.'}</p></div><label class="review-confirm"><input type="checkbox" id="review-evidence"> I reviewed both documents and the comparison evidence.</label><div class="actions"><button id="review-csv" class="button primary" disabled>Export reviewed CSV</button><button id="review-json" class="button secondary" disabled>JSON + evidence</button></div><p class="hint">No payment is approved or initiated from this demo. Downloaded records include the review status and payment hold.</p></div></section></div>`;
 if(mismatch){$('#make-draft').onclick=()=>{$('#correction-text').hidden=false;$('.draft-label').hidden=false;$('#download-draft').hidden=false;$('#correction-text').value=correctionDraft(invoice,po,result);$('#make-draft').disabled=true;message('Correction request drafted. Review and edit it before downloading.');};$('#download-draft').onclick=()=>{download($('#correction-text').value,'correction-request.txt','text/plain');message('Draft downloaded. No message was sent.');};}
 $('#review-evidence').onchange=e=>{reviewed=e.target.checked;$('#review-csv').disabled=!reviewed;$('#review-json').disabled=!reviewed;};
 const exportData=format=>{try{const data=reviewedExport(invoice,po,result,reviewed);download(format==='csv'?reviewCsv(data):JSON.stringify(data,null,2),`reviewed-comparison.${format}`,format==='csv'?'text/csv':'application/json');message('Reviewed data exported. Payment remains '+data.paymentStatus.replaceAll('_',' ').toLowerCase()+'.');}catch(e){message(e.message);}};$('#review-csv').onclick=()=>exportData('csv');$('#review-json').onclick=()=>exportData('json');
}
window.addEventListener('invoicing-reset',()=>{invoice=null;po=null;invalidate();$('#match-invoice').value='';$('#match-po').value='';renderSources();});
